package com.example.lending.adapter.out.persistence;

import jakarta.persistence.LockModeType;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Lock;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;

import java.util.Optional;
import java.util.UUID;

public interface MemberJpaRepository extends JpaRepository<MemberJpaEntity, UUID> {

    @Lock(LockModeType.PESSIMISTIC_WRITE)
    @Query("select m from MemberJpaEntity m where m.id = :id")
    Optional<MemberJpaEntity> findByIdForUpdate(@Param("id") UUID id);
}
package com.example.lending.application.port.in;

import com.example.lending.application.port.out.LoadMemberLoansPort.MemberLoanPage;

import java.util.UUID;

public interface GetMemberLoansUseCase {

    int MAX_PAGE_SIZE = 100;

    MemberLoanPage getActiveLoans(GetMemberLoansQuery query);

    // page 는 0부터 시작한다
    record GetMemberLoansQuery(UUID memberId, int page, int size) {

        public GetMemberLoansQuery {
            if (memberId == null) {
                throw new IllegalArgumentException("memberId is required");
            }
            if (page < 0) {
                throw new IllegalArgumentException("page must not be negative");
            }
            if (size < 1 || size > MAX_PAGE_SIZE) {
                throw new IllegalArgumentException("size must be between 1 and " + MAX_PAGE_SIZE);
            }
        }
    }
}
package com.example.lending.application.service;

import com.example.lending.application.port.in.GetMemberLoansUseCase;
import com.example.lending.application.port.out.LoadMemberLoansPort;
import com.example.lending.application.port.out.LoadMemberLoansPort.MemberLoanPage;
import com.example.lending.application.port.out.LoadMemberPort;
import com.example.lending.domain.MemberNotFoundException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
@Transactional(readOnly = true)
public class GetMemberLoansService implements GetMemberLoansUseCase {

    private final LoadMemberPort loadMemberPort;
    private final LoadMemberLoansPort loadMemberLoansPort;

    public GetMemberLoansService(LoadMemberPort loadMemberPort, LoadMemberLoansPort loadMemberLoansPort) {
        this.loadMemberPort = loadMemberPort;
        this.loadMemberLoansPort = loadMemberLoansPort;
    }

    @Override
    public MemberLoanPage getActiveLoans(GetMemberLoansQuery query) {
        loadMemberPort.loadMember(query.memberId())
                .orElseThrow(() -> new MemberNotFoundException(query.memberId()));
        return loadMemberLoansPort.loadActiveLoans(query.memberId(), query.page(), query.size());
    }
}
package com.example.lending;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.MockMvc;

import java.time.LocalDate;
import java.util.UUID;

import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

@SpringBootTest
@AutoConfigureMockMvc
class LendingIntegrationTest {

    @Autowired
    MockMvc mockMvc;

    @Autowired
    ObjectMapper objectMapper;

    @Test
    void loaning_a_book_already_on_loan_returns_409() throws Exception {
        String book = registerBook();
        String memberId = registerMember();
        String loanRequest = loanRequest(book, memberId);

        mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON).content(loanRequest))
                .andExpect(status().isCreated())
                .andExpect(jsonPath("$.bookId").value(book));

        String otherMemberRequest = loanRequest(book, registerMember());
        mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON).content(otherMemberRequest))
                .andExpect(status().isConflict());
    }

    @Test
    void member_cannot_borrow_more_than_five_books_at_once() throws Exception {
        String memberId = registerMember();
        for (int i = 0; i < 5; i++) {
            mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                            .content(loanRequest(registerBook(), memberId)))
                    .andExpect(status().isCreated());
        }

        mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                        .content(loanRequest(registerBook(), memberId)))
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.error").value("LOAN_LIMIT_EXCEEDED"));
    }

    @Test
    void loan_limit_is_per_member() throws Exception {
        String fullMember = registerMember();
        for (int i = 0; i < 5; i++) {
            mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                            .content(loanRequest(registerBook(), fullMember)))
                    .andExpect(status().isCreated());
        }

        mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                        .content(loanRequest(registerBook(), registerMember())))
                .andExpect(status().isCreated());
    }

    @Test
    void loaning_with_unregistered_member_returns_404() throws Exception {
        mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                        .content(loanRequest(registerBook(), UUID.randomUUID().toString())))
                .andExpect(status().isNotFound());
    }

    @Test
    void returning_a_loan_makes_the_book_loanable_again() throws Exception {
        String book = registerBook();
        String loanId = loan(book, registerMember());

        mockMvc.perform(post("/loans/{loanId}/return", loanId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.loanId").value(loanId))
                .andExpect(jsonPath("$.returnedAt").value(LocalDate.now().toString()));

        mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                        .content(loanRequest(book, registerMember())))
                .andExpect(status().isCreated());
    }

    @Test
    void returning_an_already_returned_loan_returns_409() throws Exception {
        String loanId = loan(registerBook(), registerMember());
        mockMvc.perform(post("/loans/{loanId}/return", loanId)).andExpect(status().isOk());

        mockMvc.perform(post("/loans/{loanId}/return", loanId))
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.error").value("ALREADY_RETURNED"));
    }

    @Test
    void returning_an_unknown_loan_returns_404() throws Exception {
        mockMvc.perform(post("/loans/{loanId}/return", UUID.randomUUID()))
                .andExpect(status().isNotFound());
    }

    @Test
    void returned_loans_do_not_count_toward_the_limit() throws Exception {
        String memberId = registerMember();
        String firstLoanId = loan(registerBook(), memberId);
        for (int i = 0; i < 4; i++) {
            loan(registerBook(), memberId);
        }
        mockMvc.perform(post("/loans/{loanId}/return", firstLoanId)).andExpect(status().isOk());

        mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                        .content(loanRequest(registerBook(), memberId)))
                .andExpect(status().isCreated());
        mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                        .content(loanRequest(registerBook(), memberId)))
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.error").value("LOAN_LIMIT_EXCEEDED"));
    }

    @Test
    void returning_on_the_due_date_has_no_late_fee() throws Exception {
        String loanId = loanOn("2026-01-01", registerBook(), registerMember());

        mockMvc.perform(post("/loans/{loanId}/return", loanId).contentType(MediaType.APPLICATION_JSON)
                        .content("{\"returnedAt\":\"2026-01-15\"}"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.returnedAt").value("2026-01-15"))
                .andExpect(jsonPath("$.overdueDays").value(0))
                .andExpect(jsonPath("$.lateFee").value(0));
    }

    @Test
    void returning_one_day_after_the_due_date_charges_100() throws Exception {
        String loanId = loanOn("2026-01-01", registerBook(), registerMember());

        mockMvc.perform(post("/loans/{loanId}/return", loanId).contentType(MediaType.APPLICATION_JSON)
                        .content("{\"returnedAt\":\"2026-01-16\"}"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.overdueDays").value(1))
                .andExpect(jsonPath("$.lateFee").value(100));
    }

    @Test
    void returning_five_days_after_the_due_date_charges_500() throws Exception {
        String loanId = loanOn("2026-01-01", registerBook(), registerMember());

        mockMvc.perform(post("/loans/{loanId}/return", loanId).contentType(MediaType.APPLICATION_JSON)
                        .content("{\"returnedAt\":\"2026-01-20\"}"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.overdueDays").value(5))
                .andExpect(jsonPath("$.lateFee").value(500));
    }

    @Test
    void returning_without_a_body_uses_today() throws Exception {
        String loanId = loan(registerBook(), registerMember());

        mockMvc.perform(post("/loans/{loanId}/return", loanId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.returnedAt").value(LocalDate.now().toString()))
                .andExpect(jsonPath("$.overdueDays").value(0))
                .andExpect(jsonPath("$.lateFee").value(0));
    }

    @Test
    void returning_before_the_loan_date_returns_400() throws Exception {
        String loanId = loanOn("2026-01-01", registerBook(), registerMember());

        mockMvc.perform(post("/loans/{loanId}/return", loanId).contentType(MediaType.APPLICATION_JSON)
                        .content("{\"returnedAt\":\"2025-12-31\"}"))
                .andExpect(status().isBadRequest());
    }

    @Test
