package com.example.lending;

import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.MockMvc;

import java.util.UUID;

import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

// 테스트들이 같은 DB 를 공유하므로 각 테스트는 고유한 태그를 제목에 넣어 다른 테스트의 도서와 섞이지 않게 한다
@SpringBootTest
@AutoConfigureMockMvc
class BookSearchIntegrationTest {

    @Autowired
    MockMvc mockMvc;

    @Autowired
    ObjectMapper objectMapper;

    @Test
    void search_matches_part_of_title_regardless_of_case() throws Exception {
        String tag = uniqueTag();
        String id = registerBook("Spring in Action " + tag);
        registerBook("Clean Architecture " + tag);

        mockMvc.perform(get("/books").param("title", tag.toUpperCase()))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.length()").value(2));

        mockMvc.perform(get("/books").param("title", "spring in"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.length()").value(1))
                .andExpect(jsonPath("$[0].id").value(id))
                .andExpect(jsonPath("$[0].title").value("Spring in Action " + tag))
                .andExpect(jsonPath("$[0].status").value("AVAILABLE"));
    }

    @Test
    void search_without_match_returns_empty_list() throws Exception {
        registerBook("Spring in Action " + uniqueTag());

        mockMvc.perform(get("/books").param("title", uniqueTag()))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.length()").value(0));
    }

    @Test
    void search_treats_like_wildcards_as_plain_text() throws Exception {
        String tag = uniqueTag();
        registerBook("Java 100% Guide " + tag);
        registerBook("Java_Basics " + tag);
        registerBook("Java Basics " + tag);

        mockMvc.perform(get("/books").param("title", "%" + tag))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.length()").value(0));

        mockMvc.perform(get("/books").param("title", "0% guide " + tag))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.length()").value(1))
                .andExpect(jsonPath("$[0].title").value("Java 100% Guide " + tag));

        mockMvc.perform(get("/books").param("title", "va_b" + " " + tag.substring(0, 0)))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.length()").value(1))
                .andExpect(jsonPath("$[0].title").value("Java_Basics " + tag));
    }

    @Test
    void search_without_title_returns_400() throws Exception {
        mockMvc.perform(get("/books"))
                .andExpect(status().isBadRequest());
        mockMvc.perform(get("/books").param("title", "   "))
                .andExpect(status().isBadRequest());
    }

    private String uniqueTag() {
        return "tag" + UUID.randomUUID().toString().replace("-", "").substring(0, 12);
    }

    private String registerBook(String title) throws Exception {
        String registered = mockMvc.perform(post("/books")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content(objectMapper.writeValueAsString(new BookBody(title))))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(registered).get("id").asText();
    }

    record BookBody(String title) {
    }
}

